using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Commands.RejectQuotation;public sealed class RejectQuotationCommandHandler(IQuotationRepository repository,IApplicationDbContext db):IRequestHandler<RejectQuotationCommand,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(RejectQuotationCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<QuotationDto>(QuotationErrors.NotFound);if(e.Status.ToString()!="Sent")return Result.Failure<QuotationDto>(QuotationErrors.NotDraft);e.Reject(request.RejectedAt);await db.SaveChangesAsync(cancellationToken);return Result.Success(QuotationDto.FromEntity(e));}}
